const item = $input.first().json;

// La salida del AI Agent normalmente viene en item.output
let aiOutput = item.output || item.text || item.response || "";

let datosViaje = {
  nombre: "No especificado",
  origen: "No especificado",
  destino: "No especificado",
  tipoPago: "No especificado"
};

try {
  if (typeof aiOutput === "string") {
    aiOutput = aiOutput
      .replace(/```json/g, "")
      .replace(/```/g, "")
      .trim();

    const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      datosViaje = JSON.parse(jsonMatch[0]);
    }
  } else if (typeof aiOutput === "object") {
    datosViaje = aiOutput;
  }
} catch (error) {
  datosViaje = {
    nombre: "No especificado",
    origen: "No especificado",
    destino: "No especificado",
    tipoPago: "No especificado"
  };
}

const camposRequeridos = {
  pasajero: datosViaje.nombre,
  origen: datosViaje.origen,
  destino: datosViaje.destino,
  tipoPago: datosViaje.tipoPago
};

const faltantes = Object.entries(camposRequeridos)
  .filter(([, valor]) =>
    typeof valor !== "string" ||
    !valor.trim() ||
    valor.trim().toLowerCase() === "no especificado"
  )
  .map(([campo]) => campo);

if (faltantes.length > 0) {
  return [
    {
      json: {
        success: false,
        mensaje: "Faltan datos para solicitar el viaje: " + faltantes.join(", ") + "."
      }
    }
  ];
}

const conductores = [
  {
    nombre: "Carlos Ramírez",
    auto: "Nissan Versa 2020",
    placas: "ABC-123-A",
    distanciaKm: 1.4,
    tiempoMin: 5
  },
  {
    nombre: "Luis Hernández",
    auto: "Toyota Corolla 2021",
    placas: "XYZ-789-B",
    distanciaKm: 2.8,
    tiempoMin: 9
  },
  {
    nombre: "Miguel Torres",
    auto: "Kia Rio 2019",
    placas: "JKL-456-C",
    distanciaKm: 0.9,
    tiempoMin: 3
  },
  {
    nombre: "Ana López",
    auto: "Hyundai Elantra 2020",
    placas: "MNO-321-D",
    distanciaKm: 3.2,
    tiempoMin: 11
  }
];

conductores.sort((a, b) => a.distanciaKm - b.distanciaKm);

const conductorAsignado = conductores[0];

return [
  {
    json: {
      success: true,
      mensaje: "Viaje despachado correctamente",
      pasajero: datosViaje.nombre || "No especificado",
      origen: datosViaje.origen || "No especificado",
      destino: datosViaje.destino || "No especificado",
      tipoPago: datosViaje.tipoPago || "No especificado",
      conductorAsignado: {
        nombre: conductorAsignado.nombre,
        auto: conductorAsignado.auto,
        placas: conductorAsignado.placas
      },
      distanciaKm: conductorAsignado.distanciaKm,
      tiempoEstimadoLlegadaMin: conductorAsignado.tiempoMin
    }
  }
];
